      if (a === 'gunluk') { if (D.gunO && D.gunO.g === GN) { const g = D.gunO; sahne(`<div class="mm-son"><h2>📅 Bugünkü sonucun</h2><div class="tutar">${para(g.odul)}</div><p>${g.n} soruyu bildin. Yarın yeni sorular gelecek.</p><button class="ana" data-a="serbest">🎲 Serbest yarışma</button><button data-a="menu">Menü</button></div>`); if (window.Seri) kok.appendChild(Seri.panel('milyoner', { etiketler: ['0–3', '4–6', '7–9', '10–11', '12 🏆'], baslik: 'Günün yarışması', api })); return; } basla(true); }
